mapper.select:
SELECT DISTINCT b.module_instance_id FROM expert_review_batch b JOIN expert_review_assignment a ON a.batch_id=b.id
 WHERE a.expert_user_id=#{userId} AND a.valid=TRUE AND a.review_status='ASSIGNED' AND b.module_instance_id IN
#{id}

SELECT DISTINCT project_id FROM module_instance
 WHERE definition_id=#{definitionId} AND project_id>#{afterProjectId}
 ORDER BY project_id LIMIT 100
